/* Builds js/data/taxonomy.js (fit tag library) and js/data/ops_extra.js (operator locations)
   from the research extracts. usage: node tools/build-taxonomy.js <scratch dir> */
const fs = require('fs'), path = require('path');
const S = process.argv[2];
const dict = require(path.join(S, 'research/_tagdict.json'));
const defs = require(path.join(S, 'research/_tagdefs.json'));
const CAT = { 'Sales Leadership': 'sales_leadership', Marketing: 'marketing', 'Revenue Operations': 'revenue_operations', 'Sales Enablement': 'sales_enablement', 'Customer Success & Growth': 'customer_success_growth', 'AI GTM': 'ai_gtm', Partnerships: 'partnerships', Sellers: 'sellers' };
const AX = { 'Sales Leadership': 'Win deals', Sellers: 'Win deals', Marketing: 'Generate demand', Partnerships: 'Generate demand', 'Revenue Operations': 'Systems & data', 'AI GTM': 'Systems & data', 'Sales Enablement': 'Build the team', 'Customer Success & Growth': 'Retain & expand' };
const title = (s) => s.replace(/\b([a-z])/g, (m, c) => c.toUpperCase()).replace(/\bAbm\b/g, 'ABM').replace(/\bCrm\b/g, 'CRM').replace(/\bSeo\b/g, 'SEO').replace(/\bAi\b/g, 'AI').replace(/\bCs\b/g, 'CS').replace(/\bPe\b/g, 'PE').replace(/\bRevops\b/g, 'RevOps').replace(/\bHubspot\b/g, 'HubSpot').replace(/\bMeddic\/meddpicc\b/gi, 'MEDDIC/MEDDPICC').replace(/\bGtm\b/g, 'GTM').replace(/\bKpi\b/g, 'KPI').replace(/\bLeandata\b/g, 'LeanData').replace(/\bAdroll\b/g, 'AdRoll').replace(/ Of /g, ' of ').replace(/ And /g, ' and ').replace(/ To /g, ' to ').replace(/ For /g, ' for ');
const out = new Map();
for (const t of dict) {
  const k = t.t.toLowerCase();
  const grp = defs.TAG_GROUP[k];
  const g = grp ? grp.split(' › ')[1] : (t.g !== t.c ? t.g : '');
  out.set(k, { v: t.t, l: t.t, c: CAT[t.c] || t.c, g, axis: t.axis, stage: t.stage, d: t.def || defs.TAG_DEF[k] || '', n: t.operators });
}
for (const [k, grp] of Object.entries(defs.TAG_GROUP)) {
  if (out.has(k)) continue;
  const [c, g] = grp.split(' › ');
  const name = title(k);
  out.set(k, { v: name, l: name, c: CAT[c] || c, g, axis: AX[c] || '', stage: '', d: defs.TAG_DEF[k] || '', n: 0 });
}
const lib = [...out.values()].sort((a, b) => b.n - a.n || a.l.localeCompare(b.l));
const dir = path.join(__dirname, '..', 'js', 'data');
fs.writeFileSync(path.join(dir, 'taxonomy.js'), '/* Generated by tools/build-taxonomy.js: fit tag library (live tags + taxonomy groups). */\nwindow.RN = window.RN || {}; RN.data = RN.data || {};\nRN.data.tagLibrary = ' + JSON.stringify(lib) + ';\nRN.data.roleGroups = ' + JSON.stringify(defs.ROLE_GROUPS || {}) + ';\n');
// Locations from the Projects prototype dataset, tidied
const src = fs.readFileSync(path.join(S, 'projects/app.js'), 'utf8');
const i = src.indexOf('var _i=['); const j = src.indexOf('];', i);
const ops = eval(src.slice(i + 7, j + 1));
const FIX = { 'Uk London': 'London, UK', 'atlanta, ga': 'Atlanta, GA', 'Chicago, Il': 'Chicago, IL', 'Boston Ma': 'Boston, MA', 'Philadephia, PA': 'Philadelphia, PA', 'Houston,Tx': 'Houston, TX', 'Singapore, 01': 'Singapore', 'Lafayette, ca': 'Lafayette, CA', 'Oceanside CA': 'Oceanside, CA', NYC: 'New York, NY', 'NYC Metro': 'New York, NY', 'New York City, NY': 'New York, NY', 'Chicago': 'Chicago, IL', 'Atlanta GA & Nashville TN USA': 'Atlanta, GA', 'Boston, Massachusetts': 'Boston, MA', 'London, United Kingdom': 'London, UK', 'London, England': 'London, UK', 'Toronto': 'Toronto, ON', 'Toronto, Ontario': 'Toronto, ON', 'Mtn. View, CA': 'Mountain View, CA', 'Santa Monica, CA (Los Angeles)': 'Santa Monica, CA' };
const loc = {};
ops.forEach((o) => { loc[o.id] = FIX[o.loc] || o.loc || ''; });
fs.writeFileSync(path.join(dir, 'ops_extra.js'), '/* Generated by tools/build-taxonomy.js: operator locations from the Projects prototype dataset. */\nwindow.RN = window.RN || {}; RN.data = RN.data || {};\nRN.data.opLocations = ' + JSON.stringify(loc) + ';\n');
console.log('tags', lib.length, 'locations', Object.keys(loc).length);
